cases.bad:
// MAIN world: posts once, no retry — if listener not yet registered, message lost forever
window.postMessage({ type: '__YT_DETECTED_SUBTITLES', tracks, videoId }, '*');
// ISOLATED content-script: CRXJS async import() delays addEventListener past document_start → listener not ready when post arrives

cases.good:
// ISOLATED content-script (receiver): post ready signal when listener registers
window.addEventListener('message', handleDetected);
window.postMessage({ type: '__YT_CS_READY' }, '*'); // announce readiness
// dedup by videoId to avoid double-process (original post + re-post both arrive)
if (data.videoId === __YT_LAST_RELAYED_VIDEO_ID) return;
__YT_LAST_RELAYED_VIDEO_ID = data.videoId;

// MAIN world (sender): cache last tracks, re-post on ready signal
let lastDetectedTracks, lastDetectedVideoId;
window.addEventListener('message', (e) => {
  if (e.data?.type === '__YT_CS_READY' && lastDetectedTracks) {
    window.postMessage({ type: '__YT_DETECTED_SUBTITLES', tracks: lastDetectedTracks, videoId: lastDetectedVideoId }, '*');
  }
});
